    mk('SA-022', 'ศักดิ์ชัย วงศ์วิวัฒน์','ศช', 'sales', 'director', 'ผู้อำนวยการฝ่ายขาย'),

    // ===== ทีมอีเว้นท์ =====
    mk('EM-001', 'มาลี รักงาน',        'มล', 'events', 'staff',    'พนักงานอีเว้นท์'),
    mk('EM-002', 'ปริญญา สุขสันต์',    'ปร', 'events', 'staff',    'พนักงานอีเว้นท์'),
    mk('EM-003', 'ธิดา บุญชู',         'ธด', 'events', 'head',     'หัวหน้าทีมอีเว้นท์'),
    mk('EM-004', 'โชคชัย มงคลพันธ์',   'ชย', 'events', 'staff',    'พนักงานอีเว้นท์')
